l = set()
l.add(1)
i = 2
while i <= 10 ** 18:
	j = 1
	while j * i <= 1000000000000000000:
		l.add(i * j)
		j *= 3
	i *= 2
lis = list(l)
lis.sort()
for _ in range(int(input())):
	cnt = 0
	(l, r) = map(int, input().split())
	for x in lis:
		if l <= x <= r:
			cnt += 1
		if x > r:
			break
	print(cnt)
